<?php require_once __DIR__.'/inc/config.php'; require_once __DIR__.'/inc/auth.php'; require_admin(); $deleted=read_orders(DELETED_ORDERS_FILE); if($_SERVER['REQUEST_METHOD']==='POST'){ $i=(int)$_POST['index']; if(isset($deleted[$i])){$orders=read_orders();$orders[]=$deleted[$i];save_orders($orders);array_splice($deleted,$i,1);save_orders($deleted,DELETED_ORDERS_FILE);}} admin_header('Restore Orders'); ?><section class="admin-panel"><h2>Restore deleted orders</h2><?php if(!$deleted):?><p>No deleted orders.</p><?php else:?><table class="orders-table"><tr><th>Order ID</th><th>Customer</th><th>Items</th><th>Action</th></tr><?php foreach($deleted as $i=>$o):?><tr><td><?=e($o['orderId']??'')?></td><td><?=e($o['customer']??'')?></td><td><?=e($o['name']??'')?></td><td><form method="post"><input type="hidden" name="index" value="<?=$i?>"><button class="btn">Restore</button></form></td></tr><?php endforeach;?></table><?php endif;?><p><a href="admin.php">Back to orders</a></p></section><?php admin_footer();?>
